import React, { useState, useEffect } from 'react';
// 🟢 මෙතන axios වෙනුවට axiosInstance ලෙස නිවැරදි කරන ලදි
import axiosInstance from 'axios';

export default function TeacherQuiz({ userName, subject, qualifications }) {
  const [quizzes, setQuizzes] = useState([]);
  const [masterBank, setMasterBank] = useState([]);
  const [selectedQuizId, setSelectedQuizId] = useState('');
  
  // Quiz Create State
  const [quizTitle, setQuizTitle] = useState('');
  
  // Master Question Form States
  const [editingId, setEditingId] = useState(null);
  const [qText, setQText] = useState('');
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');
  const [correctOpt, setCorrectOpt] = useState('A');
  const [qMarks, setQMarks] = useState(2);

  const fullSubject = subject || 'Grade 9 - IT';
  const subjectParts = fullSubject.split(' - ');
  const teachingGrade = subjectParts.length > 1 ? subjectParts[0] : 'Grade 9';
  let teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  // 🟢 ඩේටාබේස් එකේ subjects ටේබල් එකේ ඇති ඇත්තම නමට (ICT) ගැලපෙන ලෙස සකස් කිරීම
  if (teachingSubject === 'IT' || teachingSubject === 'Information Technology') {
    teachingSubject = 'ICT';
  }

  // ඩේටාබේස් එකෙන් දත්ත ලෝඩ් කිරීම - axiosInstance මගින් නිවැරදි URL එකට යොමු කෙරේ
  const refreshData = () => {
    axiosInstance.get('http://localhost:8081/api/quizzes').then(res => setQuizzes(res.data)).catch(err => console.log(err));
    axiosInstance.get('http://localhost:8081/api/question-bank').then(res => setMasterBank(res.data)).catch(err => console.log(err));
  };

  useEffect(() => { refreshData(); }, []);

  // 🟢 1. අලුත් Quiz Paper එකක් ක්‍රියේට් කිරීම
  const handleCreatePaper = (e) => {
    e.preventDefault();
    const payload = { title: quizTitle, grade: teachingGrade, subject: teachingSubject, teacher_name: userName };
    axiosInstance.post('http://localhost:8081/api/add-quiz', payload).then(res => {
      if (res.data.status === "Success") {
        alert(`✅ Quiz Paper "${quizTitle}" Created! Now select it from dropdown to add questions.`);
        setQuizTitle(''); refreshData();
      }
    });
  };

  // 🟢 2. ප්‍රශ්න එකතු කිරීම හෝ එඩිට් කිරීම (දැන් වැරදි සියල්ල ඇලර්ට් එකකින් පෙන්වයි)
  const handleSaveQuestion = (e) => {
    e.preventDefault();
    
    // 🛑 Dropdown එකෙන් පේපර් එකක් තෝරලා නැත්නම් ප්‍රශ්න ඇඩ් කරන්න දෙන්න එපා
    if (!selectedQuizId) {
      alert("⚠️ Please select a target Quiz Paper from Step 2 dropdown before adding questions!");
      return;
    }

    const payload = {
      quiz_id: parseInt(selectedQuizId), question_text: qText, marks: qMarks,
      option_a: optA, option_b: optB, option_c: optC, option_d: optD, correct_option: correctOpt
    };

    if (editingId) {
      axiosInstance.put(`http://localhost:8081/api/edit-question/${editingId}`, payload).then(res => {
        if (res.data.status === "Success") {
          alert("✅ Question Content Updated!");
          setEditingId(null); clearForm(); refreshData();
        } else {
          alert(`❌ Update Failed: ${res.data.error || "Unknown Error"}`);
        }
      }).catch(err => alert("❌ Error: " + err.message));
    } else {
      axiosInstance.post('http://localhost:8081/api/add-question', payload).then(res => {
        if (res.data.status === "Success") {
          alert("✅ Question Saved & Added to Paper!");
          clearForm(); refreshData();
        } else {
          // 🟢 ඩේටාබේස් එකෙන් එන සැබෑ වැරැද්ද (error එක) නිහඬ නොවී ඇලර්ට් එකකින් බලාගැනීම
          alert(`❌ Save Failed: ${res.data.error || "Unknown Error"}`);
        }
      }).catch(err => alert("❌ Error: " + err.message));
    }
  };

  // 🟢 3. බැංකුවේ තියෙන ප්‍රශ්නයක් තවත් පේපර් එකකට Quick ඇඩ් කිරීම
  const handleQuickLink = (question) => {
    if (!selectedQuizId) { alert("Please select a target Quiz Paper from top dropdown first!"); return; }
    const payload = { ...question, quiz_id: selectedQuizId };
    
    axiosInstance.put(`http://localhost:8081/api/edit-question/${question.id}`, payload).then(res => {
      alert("➕ Linked to selected paper!");
      refreshData();
    });
  };

  const clearForm = () => {
    setQText(''); setOptA(''); setOptB(''); setOptC(''); setOptD(''); setCorrectOpt('A');
  };

  const handleStartEdit = (q) => {
    setEditingId(q.id); setQText(q.question_text);
    setOptA(q.option_a); setOptB(q.option_b); setOptC(q.option_c); setOptD(q.option_d);
    setCorrectOpt(q.correct_option); setQMarks(q.marks);
  };

  const activePaperQuestions = masterBank.filter(q => q.quiz_id === parseInt(selectedQuizId));

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif' }}>
      <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📝 Quiz & Question Manager ({teachingSubject})</h2>
      
      {/* Top Section */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginBottom: '25px' }}>
        <div style={styles.card}>
          <h4 style={{ margin: '0 0 10px 0', color: '#15803d' }}>Step 1: Create a Quiz Paper Title</h4>
          <form onSubmit={handleCreatePaper} style={{ display: 'flex', gap: '10px' }}>
            <input type="text" placeholder="e.g., Lesson 01 Quiz" value={quizTitle} onChange={e => setQuizTitle(e.target.value)} required style={styles.fullInput} />
            <button type="submit" style={{...styles.btn, backgroundColor: '#15803d'}}>Create Paper</button>
          </form>
        </div>

        <div style={styles.card}>
          <h4 style={{ margin: '0 0 10px 0', color: '#2563eb' }}>Step 2: Select Quiz Paper to Manage</h4>
          <select value={selectedQuizId} onChange={e => setSelectedQuizId(e.target.value)} style={styles.fullInput}>
            <option value="">-- Choose Quiz Paper Destination --</option>
            {quizzes.filter(q => q.subject_name === teachingSubject).map(q => (
              <option key={q.id} value={q.id}>{q.title}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Main Grid Workspace */}
      <div style={{ display: 'grid', gridTemplateColumns: '1.1fr 1.3fr', gap: '30px', alignItems: 'start' }}>
        
        {/* LEFT WORKSPACE: MASTER FORM */}
        <div style={styles.card}>
          <h3 style={{color: editingId ? '#f59e0b' : '#1e293b'}}>{editingId ? "✏️ Edit Question Content" : "➕ Type New Question"}</h3>
          <form onSubmit={handleSaveQuestion} style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '15px' }}>
            <div><label style={styles.label}>Question Text</label><input type="text" placeholder="Type your question here..." value={qText} onChange={e => setQText(e.target.value)} required style={styles.fullInput} /></div>
            
            <div style={{ display: 'flex', gap: '10px' }}>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'A'} onChange={() => setCorrectOpt('A')} /><input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'B'} onChange={() => setCorrectOpt('B')} /><input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required style={styles.fullInput} /></div>
            </div>
            <div style={{ display: 'flex', gap: '10px' }}>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'C'} onChange={() => setCorrectOpt('C')} /><input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'D'} onChange={() => setCorrectOpt('D')} /><input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} required style={styles.fullInput} /></div>
            </div>
            
            <button type="submit" style={{...styles.btn, backgroundColor: '#2563eb', padding: '12px'}}>
              {editingId ? "Save Changes Live 💾" : "Save & Add to Selected Paper 📥"}
            </button>
            {editingId && <button type="button" onClick={() => { setEditingId(null); clearForm(); }} style={{background:'#cbd5e1', border:'none', padding:'8px', borderRadius:'6px', cursor:'pointer'}}>Cancel Edit</button>}
          </form>

          {selectedQuizId && (
            <div style={{marginTop: '25px', borderTop: '2px solid #f1f5f9', paddingTop: '15px'}}>
              <h4 style={{color: '#2563eb', margin: '0 0 10px 0'}}>Questions inside this Paper ({activePaperQuestions.length})</h4>
              {activePaperQuestions.map((q, idx) => (
                <div key={q.id} style={{fontSize: '13px', background: '#f8fafc', padding: '8px 12px', borderRadius: '6px', marginBottom: '8px', display: 'flex', justifyContent: 'space-between'}}>
                  <span>{idx+1}. {q.question_text}</span>
                  <button onClick={() => handleStartEdit(q)} style={{color:'#2563eb', border:'none', background:'none', cursor:'pointer', fontWeight:'bold'}}>Edit</button>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* RIGHT WORKSPACE: Repositoy Summary */}
        <div>
          <h3 style={{ marginBottom: '15px', color: '#1e293b' }}>📚 All Created Questions (Question Bank Repository)</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', maxHeight: '500px', overflowY: 'auto', paddingRight: '5px' }}>
            {masterBank.map((q, idx) => {
              const linkedQuiz = quizzes.find(qz => qz.id === q.quiz_id);
              return (
                <div key={q.id} style={{ backgroundColor: 'white', padding: '15px', borderRadius: '10px', border: '1px solid #e2e8f0' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', color: '#64748b', marginBottom: '5px' }}>
                    <span>Question Ref #{q.id}</span>
                    <span style={{color: linkedQuiz ? '#16a34a' : '#ef4444', fontWeight: 'bold'}}>
                      {linkedQuiz ? `Linked to: ${linkedQuiz.title}` : "📌 Just in Bank"}
                    </span>
                  </div>
                  <h4 style={{ margin: '0 0 8px 0', fontSize: '14px' }}>{q.question_text}</h4>
                  
                  <div style={{display: 'flex', gap: '10px', marginTop: '10px'}}>
                    <button onClick={() => handleStartEdit(q)} style={styles.miniBtn}>✏️ Edit Content</button>
                    <button onClick={() => handleQuickLink(q)} disabled={!selectedQuizId} style={{...styles.miniBtn, backgroundColor: selectedQuizId ? '#16a34a' : '#cbd5e1', color: selectedQuizId ? 'white' : '#64748b'}}>
                      ➕ Quick Link to Selected Paper
                    </button>
                  </div>
                </div>
              );
            })}
            {masterBank.length === 0 && (
              <p style={{color:'#94a3b8', textAlign:'center'}}>No questions typed yet. Start typing on the left form!</p>
            )}
          </div>
        </div>

      </div>
    </div>
  );
}

const styles = {
  card: { backgroundColor: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)', border: '1px solid #e2e8f0' },
  fullInput: { width: '100%', padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '14px', boxSizing: 'border-box' },
  btn: { color: 'white', border: 'none', padding: '10px 20px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', whiteSpace: 'nowrap' },
  label: { display: 'block', fontSize: '12px', fontWeight: 'bold', color: '#475569', marginBottom: '5px' },
  optRow: { display: 'flex', alignItems: 'center', gap: '8px', width: '100%' },
  miniBtn: { padding: '5px 10px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', borderRadius: '6px', cursor: 'pointer', fontSize: '11px', fontWeight: 'bold', color: '#334155' }
};
